    if (!lookup->ef_DAT_file) {
        return;
    }
    if (lookup->data) {
        return;
    }
    {
        bool chk = lbArchive_80017040(NULL, lookup->ef_DAT_file, &spC,
                                      lookup->effDataTable_name, 0);
        if ((u32) spC->ef_DAT_file | (u32) spC->effDataTable_name) {
            if (chk) {
                psInitDataBankLoad(idx, (void*) spC->ef_DAT_file,
