void efAsync_LoadSync(int idx)
{
    EF_DAT_Entry* lookup;

    if (idx >= 50 || idx < 0) {
        return;
    }
    lookup = &efAsync_DatEntries[idx];
    if (!lookup->ef_DAT_file || lookup->data) {
        return;
    }
    pf_ssbm_native_effect_bank_require(
        idx, lookup->ef_DAT_file, lookup->effDataTable_name,
        &lookup->data);
}
